SELECT -- * DOJ, -- sales_channel, operator_id, '' BO_Name, COUNT(DISTINCT tin) overall_txn_count, COUNT(DISTINCT CASE WHEN (CAST(operator_id AS VARCHAR) ||'-'|| offer_type_name) IN ('22223-NANDAN', '24470-RKTBUS', '10027-MAHENDRA10', '29568-NAVEEN10', '22587-JAGIRDAR10', '16356-CITIZEN10', '22545-CITIZEN', '34157-XELITE10', '21131-ASHIRWAD10', '19269-RAJDHANI10', '23633-LAXMI10', '34117-GAURI10', '24396-LUCKY10', '30642-FASTLANE10', '20177-GUPTA10', '29421-SHREE10', '18375-AJAY10', '24952-ANSARI10', '24393-PAREEK50', '10572-MAHALAXMI10', '16022-SANJAY10', '27662-PSR10', '30426-FLIX15', '35276-RCTBUS', '10142-SAIRAM100', '9748-PURPLEEV10', '20437-INTRCITY', '23971-NUEGO5') OR (CAST(operator_id AS VARCHAR) ||'-'|| payment_system_ref_no) IN ('22223-NANDAN', '24470-RKTBUS', '10027-MAHENDRA10', '29568-NAVEEN10', '22587-JAGIRDAR10', '16356-CITIZEN10', '22545-CITIZEN', '34157-XELITE10', '21131-ASHIRWAD10', '19269-RAJDHANI10', '23633-LAXMI10', '34117-GAURI10', '24396-LUCKY10', '30642-FASTLANE10', '20177-GUPTA10', '29421-SHREE10', '18375-AJAY10', '24952-ANSARI10', '24393-PAREEK50', '10572-MAHALAXMI10', '16022-SANJAY10', '27662-PSR10', '30426-FLIX15', '35276-RCTBUS', '10142-SAIRAM100', '9748-PURPLEEV10', '20437-INTRCITY', '23971-NUEGO5') OR payment_system IN ('OPOFFER', 'OP_SL_OFFER') THEN tin END) AS op_offer_tin, -- COUNT(DISTINCT CASE WHEN payment_system IN ('OP_SL_OFFER') THEN tin END) AS op_sl_offer_tin, COUNT(DISTINCT CASE WHEN payment_system IN ('OPOFFER', 'OP_SL_OFFER') THEN tin END) AS all_offer_tin FROM ( SELECT * -- DISTINCT p.payment_system -- DATE(DATE_ADD('MINUTE', 330, t.date_of_journey)) AS DOJ, -- t.operator_id, t.tin, p.offer_type_name, -- p.payment_system, p.payment_system_ref_no, t.sales_channel FROM transaction.bus_ticket_events t LEFT JOIN "transaction"."bus_payment_events" p ON p.order_uuid = t.order_uuid WHERE p.time_of_event >= TIMESTAMP '2026-05-01 18:30:00' AND p.time_of_event < TIMESTAMP '2026-06-15 18:30:00' AND p.country_code = 'IND' AND t.date_of_journey >= TIMESTAMP '2026-05-31 18:30:00' AND t.date_of_journey < TIMESTAMP '2026-06-15 18:30:00' AND t.country_code = 'IND' AND t.rb_user_id > 0 AND t.tin IN ('TV6X46176902', 'TV7956794714') AND t.sales_channel IN ('RB:MOBILEWEB#droidapp', 'RB:MOBILEWEB#iosapp', 'WEBDIRECT', 'MOBILEWEB') AND t.operator_id IN (22223, 24470, 10027, 29568, 22587, 16356, 22545, 34157, 21131, 19269, 23633, 34117, 24396, 30642, 20177, 29421, 18375, 24952, 24393, 10572, 16022, 27662, 30426, 35276, 10142, 9748, 20437, 23971) AND t.tin IS NOT NULL AND t.event_class = 2 AND t.event_type = 101 ) a GROUP BY 1 , 2, 3 ORDER BY 1, 2
